    box-sizing: border-box;
    position: relative;
    /* Keep the disclosure and actions in one row; content spans both columns. */
    display: grid;
    grid-template-columns: minmax(0, 1fr) auto;
    /* Contain CodeMirror's z-index so the header can paint above it. */
    isolation: isolate;

    /* Lift an open tooltip's stacking context above subsequent sibling panels. */
    &:has(.qg-icon-button:hover, .qg-icon-button:focus-visible, .qg-icon-button-tooltip:hover) {
        z-index: 2;
    }

    & > .qg-collapsible-panel-toggle {
        /* Paint the interactive header above any high-z-index body widgets. */
        position: relative;
        z-index: 1;
        grid-column: 1;
        grid-row: 1;

        /* Lay out the header contents in a row. */
        display: flex;
        align-items: center;
        gap: 0.4em;
        min-width: 0;
        padding: 0.5em;
        /* Reset native button styles without losing keyboard semantics. */
        border: 0;
        border-radius: 0;
        border-start-start-radius: var(--qg-panel-inner-radius);
        color: inherit;
        background: transparent;
        font: inherit;
        font-weight: 600;
        text-align: start;
        user-select: none;
        cursor: pointer;

        &:focus-visible {
            z-index: 2;
            outline: 2px solid var(--qg-focus);
            outline-offset: 1px;
        }

        & .qg-collapsible-panel-chevron {
            width: 1em;
            height: 1em;
            flex: 0 0 auto;
            fill: none;
            stroke: currentColor;
            stroke-width: 1.75;
            stroke-linecap: round;
            stroke-linejoin: round;
            transform-origin: center;
            transition: transform 0.12s ease;
        }
    }

    &[data-expanded] > .qg-collapsible-panel-toggle .qg-collapsible-panel-chevron {
        transform: rotate(90deg);
    }

    /* Use red to distinguish panels that need attention. */
    &.qg-highlighted {
        border-color: var(--qg-danger);
        box-shadow:
            0 2px 6px color-mix(in srgb, var(--qg-danger) 12%, transparent),
            0 1px 2px color-mix(in srgb, var(--qg-danger) 10%, transparent);

        & > .qg-collapsible-panel-toggle {
            color: var(--qg-danger);
            background: var(--qg-danger-subtle);
        }

        & > .qg-collapsible-panel-actions {
            color: var(--qg-danger);
            background: var(--qg-danger-subtle);
        }
    }
}

.qg-attention-needed-icon {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 1.25em;
    height: 1.25em;
    border-radius: 50%;
    color: var(--qg-surface);
    background: var(--qg-danger);
    font-size: 0.85em;
    font-weight: bold;
}

.qg-collapsible-panel-actions {
    /* Use the panel border as the group's outer border. */
    display: flex;
    z-index: 1;
    grid-column: 2;
    grid-row: 1;
    border-inline-start: 1px solid var(--qg-border);
    border-start-end-radius: var(--qg-panel-inner-radius);

    & > .qg-icon-button-wrapper {
        align-self: stretch;
    }

    & > .qg-icon-button-wrapper + .qg-icon-button-wrapper {
        border-inline-start: 1px solid var(--qg-border);
    }

    & .qg-icon-button {
        height: 100%;
        border: 0;
        border-radius: 0;
        background: transparent;
    }

    & > .qg-icon-button-wrapper:last-child .qg-icon-button {
        /* Follow the inside edge of the panel's top-end corner. */
        border-start-end-radius: var(--qg-panel-inner-radius);
    }
}

.qg-collapsible-panel:not([data-expanded]) > .qg-collapsible-panel-actions > .qg-icon-button-wrapper:last-child .qg-icon-button {
    /* In a collapsed panel, the action also meets the bottom-end corner. */
    border-end-end-radius: var(--qg-panel-inner-radius);
}

.qg-collapsible-panel:not([data-expanded]) > .qg-collapsible-panel-actions {
    /* Clip the group's own background to the exposed bottom-end corner. */
    border-end-end-radius: var(--qg-panel-inner-radius);
}

.qg-collapsible-panel:not([data-expanded]) > .qg-collapsible-panel-toggle {
    /* Complete the bottom-start corner when content is hidden. */
    border-end-start-radius: var(--qg-panel-inner-radius);
}

.qg-collapsible-panel:not(:has(> .qg-collapsible-panel-actions)) > .qg-collapsible-panel-toggle {
    /* Complete the top-end corner when there is no action group. */
    border-start-end-radius: var(--qg-panel-inner-radius);
}

.qg-collapsible-panel:not([data-expanded]):not(:has(> .qg-collapsible-panel-actions)) > .qg-collapsible-panel-toggle {
    /* Complete the remaining corner when collapsed without actions. */
    border-end-end-radius: var(--qg-panel-inner-radius);
}

.qg-collapsible-panel-title {
    /* Let long titles shrink beside the action group. */
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.qg-panel-highlight-indicator {
    display: inline-block;
    width: 0.65em;
    height: 0.65em;
    margin-inline-start: 0.4em;
    border-radius: 50%;
    vertical-align: 0.05em;
    background: var(--qg-accent);
    visibility: hidden;
}

.qg-panel-highlight-indicator-active {
    visibility: visible;
    animation: qg-panel-highlight-pulse 1.4s ease-in-out infinite;
}

/* Hide the cue once the expanded panel shows its highlighted content. */
.qg-collapsible-panel[data-expanded] .qg-panel-highlight-indicator {
    visibility: hidden;
}

@keyframes qg-panel-highlight-pulse {
    0%,
    100% {
        opacity: 0.55;
        box-shadow: 0 0 0 0 color-mix(in srgb, var(--qg-accent) 45%, transparent);
    }

    50% {
        opacity: 1;
        box-shadow: 0 0 0 0.4em color-mix(in srgb, var(--qg-accent) 0%, transparent);
    }
}

@media (prefers-reduced-motion: reduce) {
    .qg-panel-highlight-indicator-active {
        animation: none;
    }

    .qg-collapsible-panel > .qg-collapsible-panel-toggle .qg-collapsible-panel-chevron {
        transition: none;
    }
}

.qg-collapsible-panel-content {
    /* Establish the lower half of the panel-local stacking order described above. */
    position: relative;
    z-index: 0;
    grid-column: 1 / -1;
    /* Constrain the body and separate it visually from the header. */
    max-height: 70vh;
    overflow: auto;
    padding: 0.75em;
    border-top: 1px solid var(--qg-border);
}

/* Keep panel padding with content when the panel delegates scrolling to a ScrollableArea. */
.qg-collapsible-panel-content:has(> .qg-scrollable-area) {
    padding: 0;

    & > .qg-scrollable-area {
        max-height: min(20em, 35dvh);
    }

    & > .qg-scrollable-area > .qg-scrollable-area-content {
        padding: 0.75em;
    }
}
