    box-sizing: border-box;
    --qg-icon-cutout: var(--qg-canvas);
    display: flex;
    flex-direction: column;
    border: 1px solid transparent;
    border-radius: var(--qg-border-radius);
    padding: .3em .5em;
    transition-property: border-color, background-color, box-shadow;
    transition-duration: 0.2s;

    & > .qg-graph-node-head,
    & > .qg-color-bar {
        flex: none;
    }

    & > .qg-graph-node-body-wrapper {
        flex: 1 1 auto;
        min-height: 0;
    }

    &.qg-no-props {
        cursor: default;
    }

    &.qg-collapsed:hover,
    &.qg-expanded,
    &.qg-resizing {
        --qg-icon-cutout: var(--qg-surface);
        cursor: pointer;
        background-color: var(--qg-surface);
        border-color: var(--qg-border);
        box-shadow: var(--qg-panel-shadow);
    }

    &.qg-highlighted {
        border-color: var(--qg-focus);
        box-shadow: 0 0 0 2px var(--qg-focus);
    }
}

@media (forced-colors: active) {
    .qg-graph-node.qg-highlighted {
        outline: 2px solid Highlight;
    }
}

.qg-graph-node.qg-resizing {
    overflow: hidden;
}

.query-graph .qg-subtree-toggle {
    position: absolute;
    left: 50%;
    width: .7em;
    height: .7em;
    bottom: 0;
    padding: 0;
    transform: translate(-50%, 50%);
    border: 0;
    background: none;
    color: inherit;
    font: inherit;
    cursor: pointer;

    &.qg-collapsed {
        opacity: 0;
    }

    &.qg-descendant-highlighted {
        opacity: 1;

        & .qg-subtree-handle-background {
            animation: qg-descendant-highlight-pulse 0.8s ease-in-out infinite alternate;
        }
    }

    &:focus-visible {
        opacity: 1;
    }

    &:hover {
        color: var(--qg-subtree-handle-hover-text);

        & .qg-subtree-handle-background {
            fill: var(--qg-subtree-handle-hover);
        }
    }
}

@keyframes qg-descendant-highlight-pulse {
    from {
        fill: var(--qg-accent-subtle);
        stroke: var(--qg-focus);
        stroke-width: 1.5;
    }

    to {
        fill: var(--qg-accent);
        stroke: var(--qg-focus);
        stroke-width: 3;
    }
}

@media (prefers-reduced-motion: reduce) {
    .query-graph .qg-subtree-toggle.qg-descendant-highlighted .qg-subtree-handle-background {
        animation: none;
        fill: var(--qg-accent-subtle);
        stroke: var(--qg-focus);
        stroke-width: 2.5;
    }
}

@media (forced-colors: active) {
    .query-graph .qg-subtree-toggle.qg-descendant-highlighted .qg-subtree-handle-background {
        animation: none;
        fill: Canvas;
        stroke: Highlight;
        stroke-width: 3;
    }
}

.qg-subtree-handle-icon {
    display: block;
    width: 100%;
    height: 100%;
    overflow: visible;

    & .qg-subtree-handle-background {
        fill: var(--qg-border);
        stroke: var(--qg-border);
        stroke-width: 1.5;
        transition: fill 0.2s;
    }

    & path {
        fill: none;
        stroke: currentColor;
        stroke-width: 1.75;
        stroke-linecap: round;
    }

    & .qg-subtree-handle-vertical {
        transition: opacity 0.12s ease;

        .qg-subtree-toggle.qg-expanded & {
            opacity: 0;
        }
    }
}

.query-graph .react-flow__node-querynode:hover .qg-subtree-toggle {
    opacity: 1;
}

.qg-graph-node-head {
    width: max-content;
    margin: auto;
    text-align: center;
}

/* A bar drawn above and/or below the node.
 * Several colors are split into equal segments. */
.qg-color-bar {
    display: flex;
    gap: 1px;
    width: 2.4em;
    height: 4px;
    margin-left: auto;
    margin-right: auto;
}
.qg-color-bar-above {
    margin-bottom: 4px;
}
.qg-color-bar-below {
    margin-top: 4px;
}
.qg-color-bar-seg {
    flex: 1 1 0;
    border-radius: 2px;
}

.qg-graph-node-label {
    /*
     * Clip the label at some length; long labels can become quite unreadable
     */
    max-width: 10em;
    text-overflow: ellipsis;
    overflow: hidden;
    /*
     * We set up everything such that we can draw a nice background for the label.
     * If the node label should be highlighted, a \`background-color\` is set from React.
     */
    border-radius: .4em;
    padding: 0 .15em;
}

.qg-graph-node-body-wrapper {
    max-width: 0;
    max-height: 0;
    overflow: hidden;

    .qg-graph-node.qg-expanded &,
    .qg-graph-node.qg-resizing & {
        max-width: 30em;
        max-height: 20em;
    }
}
.qg-graph-node-body {
    width: max-content;
    height: max-content;
    max-width: 30em;
    max-height: 20em;

    .qg-graph-node.qg-expanded & > .qg-scrollable-area-content,
    .qg-graph-node.qg-resizing & > .qg-scrollable-area-content {
        padding-bottom: 0.6em;
    }
}

.qg-prop-name {
    color: var(--qg-text-muted);
    -webkit-user-select: none;
    -ms-user-select: none;
    user-select: none;
}

.qg-prop-value {
    -webkit-user-select: text;
    -ms-user-select: text;
    user-select: text;
}
