.file-selection-page-content {
    width: 35em;
    min-width: 40%;
    max-width: 100%;
    display: flex;
    flex-direction: column;
    align-items: stretch;
    row-gap: 1em;
}

.landing-footer {
    border-top: 1px solid var(--qg-border);
    margin-top: 3em;
    padding-top: 0.8em;
    font-size: 0.9em;
    text-align: center;
    color: var(--qg-text-muted);
}

.github-link {
    & a {
        color: var(--qg-text-muted);
    }
}

.build-info {
    margin-top: 0.4em;
    font-size: 0.85em;
    color: var(--qg-text-muted);
}

/* Hinted text area */

.hinted-textarea {
    display: flex;
    flex-direction: column;
    border: 1px solid var(--qg-border);
    border-radius: var(--qg-border-radius);
    overflow: hidden;
    box-shadow: 1px 2px 5px color-mix(in srgb, var(--qg-text) 12%, transparent);

    & > textarea {
        resize: vertical;
        border: none;
        padding: 0.3em;
        color: var(--qg-text);
        background: var(--qg-surface);

        &:focus {
            outline: none;
        }
    }

    & > .textarea-hint {
        background: var(--qg-surface);
        border-top: 1px solid var(--qg-border);
        padding: 0.4em;
        color: var(--qg-text-muted);
        font-size: .8em;
