___CSS_LOADER_EXPORT___.push([module.id, `.qg-insight-category-list {
    & h3 {
        margin: 0 0 0.5em;
        font-size: 0.9em;
    }

    & ul {
        padding: 0;
        margin: 0;
        list-style: none;
    }
}

.qg-insight-category {
    display: flex;
    gap: 0.7em;
    padding: 0.3em 0.4em;
    border-radius: 4px;
    cursor: default;

    &:hover,
    &:focus-visible,
    &.qg-insight-category-active {
        background: var(--qg-accent-subtle);
    }

    &:focus-visible {
        outline: 2px solid var(--qg-focus);
    }

    & .qg-insight-category-label {
        min-width: 0;
        overflow: hidden;
        text-overflow: ellipsis;
        white-space: nowrap;
    }

    & .qg-insight-category-count {
        margin-left: auto;
        font-variant-numeric: tabular-nums;
    }
}
